function beep({f=440,t=0.15,type='square',vol=0.18,slide=0,delay=0}={}){
  const a=ac(),o=a.createOscillator(),g=a.createGain(),t0=a.currentTime+delay;
  o.type=type;o.frequency.setValueAtTime(f,t0);
