  const bp=a.createBiquadFilter();bp.type='bandpass';bp.frequency.value=f;bp.Q.value=0.8;
  const g=a.createGain();g.gain.value=vol;
  s.connect(bp).connect(g).connect(a.destination);s.start(a.currentTime+delay);
}
const SFX={
