  release(p){beep({f:300+p*500,slide:-200,t:0.2,type:'sawtooth',vol:0.22});noise({t:0.15,vol:0.25,f:3000});},
  pop(){beep({f:rand(600,900),slide:300,t:0.1,type:'square',vol:0.3});noise({t:0.08,vol:0.35,f:2000});},
  whoosh(){noise({t:0.12,vol:0.1,f:1500});},
  thud(){beep({f:90,slide:-40,t:0.12,type:'triangle',vol:0.25});},
  win(){[523,659,784,1046].forEach((f,i)=>beep({f,t:0.18,vol:0.2,type:'square',delay:i*0.12}));},
  lose(){[400,320,240,160].forEach((f,i)=>beep({f,t:0.2,vol:0.2,type:'sawtooth',delay:i*0.15}));},
};

