let balloons=[],arrows=[],parts=[],floaters=[],shake=0;
function spawnBalloon(){
  const fromLeft=Math.random()<0.5;
  const speed=rand(18,45)+level*8;
  balloons.push({
    x:fromLeft?-40:W+40, y:rand(groundY()*0.15,groundY()*0.75),
